{"command": "cd .skilled/skills/cli-external-orchestration/cli-codex/assets && python3 - <<'EOF'
import re
t=open('prompt-templates.md').read().splitlines()
table_start=[i for i,l in enumerate(t) if l.startswith('## 11. TEMPLATE VARIABLES')][0]
table_end=[i for i,l in enumerate(t) if l.startswith('## 12.')][0]
defined=set()
for l in t[table_start:table_end]:
    m=re.findall(r'\| `\[([^\]]+)\]`',l)
    defined.update(m)
used={}
for i,l in enumerate(t):
    for m in re.findall(r'\[([A-Za-z][A-Za-z /_-]{1,30})\]',l):
        if i<table_start:
            used.setdefault(m,[]).append(i+1)
print("DEFINED:",sorted(defined))
print("UNDEFINED:",{k:v[:3] for k,v in sorted(used.items()) if k not in defined})
EOF"}

